-- Mimics the single SQL script `dotnet ef migrations script` would generate for an
-- "InitialCreate" migration: quoted PascalCase identifiers, GENERATED BY DEFAULT AS
-- IDENTITY primary keys, and EF's exact constraint/index naming convention
-- (PK_<Table>, FK_<DependentTable>_<PrincipalTable>_<Column>, IX_<Table>_<Column>).
--
-- Enum columns are plain `integer`, not a Postgres native ENUM type or a CHECK
-- constraint - EF Core maps C# enums to integers and enforces nothing at the database
-- level, so neither do we. Valid values are documented via COMMENT ON COLUMN only.

CREATE TABLE "Tenants" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(200) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Tenants" PRIMARY KEY ("Id")
);

CREATE TABLE "Carriers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "Name" character varying(200) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Carriers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Carriers_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id")
);
CREATE INDEX "IX_Carriers_TenantId" ON "Carriers" ("TenantId");

CREATE TABLE "Programs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "Name" character varying(200) NOT NULL,
    "LineOfBusiness" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Programs" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Programs_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id")
);
CREATE INDEX "IX_Programs_TenantId" ON "Programs" ("TenantId");
COMMENT ON COLUMN "Programs"."LineOfBusiness" IS '0=GeneralLiability, 1=CommercialProperty, 2=Cyber';

CREATE TABLE "ProgramCarrierShares" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "ProgramId" integer NOT NULL,
    "CarrierId" integer NOT NULL,
    "SharePercentage" numeric(5,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ProgramCarrierShares" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ProgramCarrierShares_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id"),
    CONSTRAINT "FK_ProgramCarrierShares_Programs_ProgramId" FOREIGN KEY ("ProgramId") REFERENCES "Programs" ("Id"),
    CONSTRAINT "FK_ProgramCarrierShares_Carriers_CarrierId" FOREIGN KEY ("CarrierId") REFERENCES "Carriers" ("Id")
);
CREATE INDEX "IX_ProgramCarrierShares_TenantId" ON "ProgramCarrierShares" ("TenantId");
CREATE INDEX "IX_ProgramCarrierShares_ProgramId" ON "ProgramCarrierShares" ("ProgramId");
CREATE INDEX "IX_ProgramCarrierShares_CarrierId" ON "ProgramCarrierShares" ("CarrierId");

CREATE TABLE "Brokers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "Name" character varying(200) NOT NULL,
    "LicenseNumber" character varying(50) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Brokers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Brokers_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id")
);
CREATE INDEX "IX_Brokers_TenantId" ON "Brokers" ("TenantId");

-- PII: FirstName, LastName, Email, DateOfBirth, address fields.
CREATE TABLE "Insureds" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "FirstName" character varying(100) NOT NULL,
    "LastName" character varying(100) NOT NULL,
    "Email" character varying(320) NOT NULL,
    "DateOfBirth" date NOT NULL,
    "AddressLine1" character varying(200) NOT NULL,
    "AddressLine2" character varying(200) NULL,
    "City" character varying(100) NOT NULL,
    "Province" character varying(2) NOT NULL,
    "PostalCode" character varying(10) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Insureds" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Insureds_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id")
);
CREATE INDEX "IX_Insureds_TenantId" ON "Insureds" ("TenantId");

CREATE TABLE "Policies" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "ProgramId" integer NOT NULL,
    "BrokerId" integer NOT NULL,
    "InsuredId" integer NOT NULL,
    "PolicyNumber" character varying(50) NOT NULL,
    "EffectiveDate" date NOT NULL,
    "ExpirationDate" date NOT NULL,
    "Status" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Policies" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Policies_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id"),
    CONSTRAINT "FK_Policies_Programs_ProgramId" FOREIGN KEY ("ProgramId") REFERENCES "Programs" ("Id"),
    CONSTRAINT "FK_Policies_Brokers_BrokerId" FOREIGN KEY ("BrokerId") REFERENCES "Brokers" ("Id"),
    CONSTRAINT "FK_Policies_Insureds_InsuredId" FOREIGN KEY ("InsuredId") REFERENCES "Insureds" ("Id")
);
CREATE INDEX "IX_Policies_TenantId" ON "Policies" ("TenantId");
CREATE INDEX "IX_Policies_ProgramId" ON "Policies" ("ProgramId");
CREATE INDEX "IX_Policies_BrokerId" ON "Policies" ("BrokerId");
CREATE INDEX "IX_Policies_InsuredId" ON "Policies" ("InsuredId");
COMMENT ON COLUMN "Policies"."Status" IS '0=Active, 1=Cancelled, 2=Expired, 3=NonRenewed';

CREATE TABLE "PolicyCoverages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "PolicyId" integer NOT NULL,
    "CoverageType" integer NOT NULL,
    "Limit" numeric(12,2) NOT NULL,
    "Deductible" numeric(12,2) NOT NULL,
    "Premium" numeric(12,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PolicyCoverages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PolicyCoverages_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id"),
    CONSTRAINT "FK_PolicyCoverages_Policies_PolicyId" FOREIGN KEY ("PolicyId") REFERENCES "Policies" ("Id")
);
CREATE INDEX "IX_PolicyCoverages_TenantId" ON "PolicyCoverages" ("TenantId");
CREATE INDEX "IX_PolicyCoverages_PolicyId" ON "PolicyCoverages" ("PolicyId");
COMMENT ON COLUMN "PolicyCoverages"."CoverageType" IS '0=GeneralLiability, 1=Property, 2=Cyber, 3=Umbrella, 4=Excess';

-- One row per transaction per coverage (matches the later dbt mart's grain): an
-- endorsement touching two coverages produces two rows here, same EffectiveDate/
-- ProcessedDate/TransactionType, different PolicyCoverageId and PremiumChange.
CREATE TABLE "PolicyTransactions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "PolicyId" integer NOT NULL,
    "PolicyCoverageId" integer NOT NULL,
    "TransactionType" integer NOT NULL,
    "EffectiveDate" date NOT NULL,
    "ProcessedDate" date NOT NULL,
    "PremiumChange" numeric(12,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_PolicyTransactions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PolicyTransactions_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id"),
    CONSTRAINT "FK_PolicyTransactions_Policies_PolicyId" FOREIGN KEY ("PolicyId") REFERENCES "Policies" ("Id"),
    CONSTRAINT "FK_PolicyTransactions_PolicyCoverages_PolicyCoverageId" FOREIGN KEY ("PolicyCoverageId") REFERENCES "PolicyCoverages" ("Id")
);
CREATE INDEX "IX_PolicyTransactions_TenantId" ON "PolicyTransactions" ("TenantId");
CREATE INDEX "IX_PolicyTransactions_PolicyId" ON "PolicyTransactions" ("PolicyId");
CREATE INDEX "IX_PolicyTransactions_PolicyCoverageId" ON "PolicyTransactions" ("PolicyCoverageId");
COMMENT ON COLUMN "PolicyTransactions"."TransactionType" IS '0=NewBusiness, 1=Endorsement, 2=Renewal, 3=Cancellation, 4=Reinstatement';

CREATE TABLE "Claims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "PolicyId" integer NOT NULL,
    "ClaimNumber" character varying(50) NOT NULL,
    "DateOfLoss" date NOT NULL,
    "ReportedDate" date NOT NULL,
    "Status" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Claims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Claims_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id"),
    CONSTRAINT "FK_Claims_Policies_PolicyId" FOREIGN KEY ("PolicyId") REFERENCES "Policies" ("Id")
);
CREATE INDEX "IX_Claims_TenantId" ON "Claims" ("TenantId");
CREATE INDEX "IX_Claims_PolicyId" ON "Claims" ("PolicyId");
COMMENT ON COLUMN "Claims"."Status" IS '0=Open, 1=Closed, 2=Reopened';

CREATE TABLE "ClaimTransactions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" integer NOT NULL,
    "ClaimId" integer NOT NULL,
    "TransactionType" integer NOT NULL,
    "TransactionDate" date NOT NULL,
    "Amount" numeric(12,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ClaimTransactions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ClaimTransactions_Tenants_TenantId" FOREIGN KEY ("TenantId") REFERENCES "Tenants" ("Id"),
    CONSTRAINT "FK_ClaimTransactions_Claims_ClaimId" FOREIGN KEY ("ClaimId") REFERENCES "Claims" ("Id")
);
CREATE INDEX "IX_ClaimTransactions_TenantId" ON "ClaimTransactions" ("TenantId");
CREATE INDEX "IX_ClaimTransactions_ClaimId" ON "ClaimTransactions" ("ClaimId");
COMMENT ON COLUMN "ClaimTransactions"."TransactionType" IS '0=Payment, 1=ReserveChange, 2=Recovery';
